import { Router } from "express";
import { asyncHandler } from "../../../shared/http/async-handler.js";
import { ensureAuthenticated, ensurePermissions } from "../../auth/middlewares/auth.middleware.js";
import { ContabilidadeController } from "../controllers/contabilidade.controller.js";
const controller = new ContabilidadeController();
export const contabilidadeRoutes = Router();
const permissoesLeitura = ["ADMINISTRADOR", "OPERADOR", "LEITURA_APENAS"];
const permissoesEscrita = ["ADMINISTRADOR", "OPERADOR"];
const permissaoExclusao = ["ADMINISTRADOR"];
contabilidadeRoutes.get("/contas-bancarias", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarContasBancarias.bind(controller)));
contabilidadeRoutes.post("/contas-bancarias", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.criarContaBancaria.bind(controller)));
contabilidadeRoutes.put("/contas-bancarias/:id", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.atualizarContaBancaria.bind(controller)));
contabilidadeRoutes.delete("/contas-bancarias/:id", ensureAuthenticated, ensurePermissions(permissaoExclusao), asyncHandler(controller.removerContaBancaria.bind(controller)));
contabilidadeRoutes.get("/lancamentos", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarLancamentos.bind(controller)));
contabilidadeRoutes.post("/lancamentos", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.criarLancamento.bind(controller)));
contabilidadeRoutes.put("/lancamentos/:id", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.atualizarLancamento.bind(controller)));
contabilidadeRoutes.patch("/lancamentos/:id/status", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.atualizarSituacaoLancamento.bind(controller)));
contabilidadeRoutes.post("/lancamentos/:id/pagamento", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.pagarLancamento.bind(controller)));
contabilidadeRoutes.delete("/lancamentos/:id", ensureAuthenticated, ensurePermissions(permissaoExclusao), asyncHandler(controller.removerLancamento.bind(controller)));
contabilidadeRoutes.get("/movimentacoes", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarMovimentacoes.bind(controller)));
contabilidadeRoutes.post("/movimentacoes", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.criarMovimentacao.bind(controller)));
contabilidadeRoutes.put("/movimentacoes/:id", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.atualizarMovimentacao.bind(controller)));
contabilidadeRoutes.delete("/movimentacoes/:id", ensureAuthenticated, ensurePermissions(permissaoExclusao), asyncHandler(controller.removerMovimentacao.bind(controller)));
contabilidadeRoutes.get("/emendas", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarEmendas.bind(controller)));
contabilidadeRoutes.post("/emendas", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.criarEmenda.bind(controller)));
contabilidadeRoutes.patch("/emendas/:id/status", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.atualizarStatusEmenda.bind(controller)));
